// Verus program: append an element to the end of a vector of ints.
use vstd::prelude::*;

verus! {

fn append(a: Vec<int>, b: int) -> (c: Vec<int>)
    requires
        // Needed because we allocate a Vec with length a.len() + 1.
        a.len() < usize::MAX,
    ensures
        // Length is exactly one greater.
        c.len() == a.len() + 1,

        // All original elements are preserved.
        forall|i: int| 0 <= i && i < a.len() ==> c[i] == a[i],

        // Last element is the appended value.
        c[a.len() as int] == b,

        // Conceptually: result sequence is original sequence + [b].
        c@ == a@ + seq![b],
{
    let n: usize = a.len();
    let mut c: Vec<int> = Vec::with_capacity(n + 1);

    let mut i: usize = 0;
    while i < n
        invariant
            i <= n,
            c.len() == i,
            c@ == a@.subrange(0, i as int),
            forall|j: int| 0 <= j && j < i as int ==> c[j] == a[j],
        decreases
            n - i,
    {
        c.push(a[i]);
        i += 1;
    }

    // At this point, c contains exactly all elements of a, in order.
    assert(c@ == a@);

    c.push(b);

    // After appending b, the conceptual concatenation property holds.
    assert(c@ == a@ + seq![b]);

    c
}

} // end verus!